/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK cameraUpdateProjection(s32, f32);                    /* extern */
extern s32 gTrackMarkerParents;

/* Calls cameraUpdateProjection with the given parameter for each of the 6 entries in the table. */ void updateAllCameraProjections(f32 param) {
    s32 *entry;
    s32 camera;
    u32 i;

    i = 0;
    entry = &gTrackMarkerParents;
    do {
        camera = *entry;
        entry += 1;
        i += 1;
        cameraUpdateProjection(camera, param);
    } while (i < 6U);
}
